+ func (mw *RateLimitMW) WriteHeaders(w http.ResponseWriter, info RateLimitInfo) {
+   w.Header().Set("X-RateLimit-Limit", strconv.Itoa(info.Limit))
+   w.Header().Set("X-RateLimit-Remaining", strconv.Itoa(info.Remaining))
+   w.Header().Set("X-RateLimit-Reset", strconv.FormatInt(info.ResetUnix, 10))
+   if info.RetryAfterSecs > 0 { w.Header().Set("Retry-After", strconv.Itoa(info.RetryAfterSecs)) }
+ }

